21	// =============================================================================
22	// HAZARD LEVEL MATHEMATICAL FORMULA
23	// hazard = ln(x + 1), where x is golden hours (timeSeconds / 3600, clamped >= 0)
24	// =============================================================================
25	
26	export function calculateHazardLevel(goldenHours: number): number {
27	  if (goldenHours < 0) return 0;
28	  return Math.round(Math.log(goldenHours + 1) * 100) / 100;
29	}
30	
31	export function calculateHazardFromTime(timeBalanceSeconds: number): { timeSeconds: number; goldenHours: number; hazardLevel: number } {
32	  const timeSeconds = Math.max(0, timeBalanceSeconds);
33	  const goldenHours = timeSeconds / 3600;
34	  const hazardLevel = calculateHazardLevel(goldenHours);
35	  return { timeSeconds, goldenHours, hazardLevel };
36	}
