148	const SAMPLE_RELIC_PREFIXES = [
149	  'Babylonian', 'Celestial', 'Abyssal', 'Aetheric', 'Sunforged', 'Resonant', 'Hyperborean', 'Elysian', 'Voidbound', 'Chronos'
150	];
151	
152	const SAMPLE_RELIC_NOUNS = [
153	  'Blade', 'Aegis', 'Scepter', 'Harmonica', 'Gauntlet', 'Pendant', 'Hourglass', 'Codex', 'Crucible', 'Prism'
154	];
155	
156	const SAMPLE_COLLECTIBLES = [
157	  { name: 'Enuma Elish Tablet Fragment', series: 'Ancient Mesopotamia', lore: 'When on high the heaven was not named, and the earth beneath yet bare no name...' },
158	  { name: 'First Edition Vinyl: Angelic Sine Waves', series: 'Harmonic Archives', lore: 'Mastered in the 432Hz harmonic chamber during the 2026 Solstice.' },
