163	function generateRandomItem(ticketType: TicketType): PullItem {
164	  // 1. Roll Rarity
165	  const roll = Math.random() * 100;
166	  let accumulated = 0;
167	  let chosenRarity: GachaRarity = 'common';
168	
169	  for (const r of Object.values(RARITY_TABLE)) {
170	    accumulated += r.weight;
171	    if (roll <= accumulated) {
172	      chosenRarity = r.rarity;
173	      break;
174	    }
175	  }
176	
177	  const categoryRoll = Math.random();
178	  const id = `item_${Date.now()}_${Math.random().toString(36).substring(2, 7)}`;
179	
180	  // Category 1: Relic (45% chance)
181	  if (categoryRoll < 0.45) {
182	    const prefix = SAMPLE_RELIC_PREFIXES[Math.floor(Math.random() * SAMPLE_RELIC_PREFIXES.length)];
183	    const noun = SAMPLE_RELIC_NOUNS[Math.floor(Math.random() * SAMPLE_RELIC_NOUNS.length)];
184	    const name = `${prefix} ${noun}`;
185	
186	    const scoreMultiplier = { common: 2.0, uncommon: 4.0, rare: 6.0, epic: 8.0, legendary: 10.0 }[chosenRarity];
187	    const score = Math.round((Math.random() * 2.0 + scoreMultiplier) * 100) / 100;
188	
189	    const rank = chosenRarity === 'legendary' ? '✦'
190	      : chosenRarity === 'epic' ? 'Ψ'
191	      : chosenRarity === 'rare' ? 'S₁'
192	      : chosenRarity === 'uncommon' ? 'A+'
193	      : 'B';
194	
195	    const atk = Math.floor(Math.random() * 15 * scoreMultiplier);
196	    const def = Math.floor(Math.random() * 12 * scoreMultiplier);
197	    const spd = Math.floor(Math.random() * 10 * scoreMultiplier);
198	    const luck = Math.floor(Math.random() * 8 * scoreMultiplier);
199	
200	    const downsideSeverity = Math.floor(Math.random() * 3) + 1;
201	    const downsidePenalty = downsideSeverity * 3;
202	
203	    return {
204	      id,
205	      name,
206	      description: `Double-edged ancient armament summoned from the ${TICKET_REGISTRY[ticketType].name}. Bestows tremendous power with a binding penalty.`,
207	      category: 'relic',
208	      rarity: chosenRarity,
209	      rank,
210	      score,
211	      origin: ticketType,
212	      iconEmoji: '⚔️',
213	      stats: [
214	        { name: 'ATK', value: atk },
215	        { name: 'DEF', value: def },
216	        { name: 'SPD', value: spd - downsidePenalty },
217	        { name: 'LUCK', value: luck },
218	      ],
219	      buffs: [
220	        {
221	          name: `${prefix} Resonance`,
222	          description: `Boosts Golden Hour yield multiplier by +${(scoreMultiplier * 2.5).toFixed(1)}%.`,
223	          magnitude: scoreMultiplier * 0.025,
224	        },
225	      ],
226	      downsides: [
227	        {
228	          name: `Curse of ${prefix}`,
229	          description: `Reduces combat movement speed by -${downsidePenalty} and increases stamina drain.`,
230	          severity: downsideSeverity,
231	        },
232	      ],
233	      pulledAt: new Date().toISOString(),
234	    };
235	  }
236	
237	  // Category 2: Collectible (30% chance)
238	  if (categoryRoll < 0.75) {
239	    const template = SAMPLE_COLLECTIBLES[Math.floor(Math.random() * SAMPLE_COLLECTIBLES.length)];
240	    const scoreMultiplier = { common: 1.5, uncommon: 3.5, rare: 5.5, epic: 7.5, legendary: 9.5 }[chosenRarity];
241	    const score = Math.round((Math.random() * 1.5 + scoreMultiplier) * 100) / 100;
242	
243	    const rank = chosenRarity === 'legendary' ? 'Ø'
244	      : chosenRarity === 'epic' ? 'Ψ'
245	      : chosenRarity === 'rare' ? 'S₂'
246	      : chosenRarity === 'uncommon' ? 'A'
247	      : 'C';
248	
249	    return {
250	      id,
251	      name: template.name,
252	      description: `Historical archival relic representing milestone achievements across dimensional worlds.`,
253	      category: 'collectible',
254	      rarity: chosenRarity,
255	      rank,
256	      score,
257	      origin: ticketType,
258	      iconEmoji: '🏺',
259	      seriesName: template.series,
260	      loreText: template.lore,
261	      pulledAt: new Date().toISOString(),
262	    };
263	  }
264	
265	  // Category 3: Multi-Attribute Energy Cores (IoT Fuel - 25% chance)
266	  const elements: ElementalAttribute[] = ['solar', 'void', 'verdant', 'celestial', 'aether'];
267	  const element = elements[Math.floor(Math.random() * elements.length)];
268	  const amount = Math.floor(Math.random() * 5 + 1) * 10;
269	
270	  return {
271	    id,
272	    name: `${ELEMENT_REGISTRY[element].name} Energy Core (${amount}u)`,
273	    description: `Multi-attribute IoT fuel cell. Used to power real-world sensory telemetry and fitness gear.`,
274	    category: 'energy-core',
275	    rarity: chosenRarity,
276	    rank: 'D',
277	    score: 1.2,
278	    origin: ticketType,
279	    iconEmoji: '⚡',
280	    energyCores: [{ attribute: element, amount }],
281	    pulledAt: new Date().toISOString(),
282	  };
283	}
284	
285	function syncVaultToBackend(get: () => GoldenHourState) {
286	  const current = get();
287	  persistVault({
288	    vault: current.vault,
289	    arenaSlots: current.arenaSlots,
290	    energyReserves: current.energyReserves,
291	    totalPulls: current.totalPulls,
292	  }).catch((err) => {
293	    console.error('[GoldenHourStore] Failed to persist vault to backend:', err);
294	  });
295	}
