297	// =============================================================================
298	// ZUSTAND STORE IMPLEMENTATION
299	// =============================================================================
300	
301	export const useGoldenHourStore = create<GoldenHourState>()(
302	  (set, get) => ({
303	    vault: [],
304	    hazardProfile: {
305	      goldenHours: 0,
306	      hazardLevel: 0,
307	    },
308	    energyReserves: {
309	      solar: 120,
310	      void: 50,
311	      verdant: 80,
312	      celestial: 30,
313	      aether: 65,
314	    },
315	    arenaSlots: [
316	      { slotIndex: 0, equippedItem: null },
317	      { slotIndex: 1, equippedItem: null },
318	      { slotIndex: 2, equippedItem: null },
319	      { slotIndex: 3, equippedItem: null },
320	    ],
321	    totalPulls: 0,
322	    totalPacksOpened: 0,
323	    lifetimeDict: {},
324	
325	    // -----------------------------------------------------------------------
326	    // PULL PACK BATCH (High-Efficiency Multi-Pull Engine)
327	    // -----------------------------------------------------------------------
328	    pullPackBatch: (deck: RawDeckPack, multiplier: number = 1, useUniversalShredderTicket: boolean = false) => {
329	      const inv = useInventoryStore.getState();
330	      const mult = Math.max(1, multiplier);
331	      const currency = deck.cost.currency;
332	      const standardCost = deck.cost.amount * mult;
333	      // 1 Shredder Ticket replaces the ENTIRE cost of 1 pack roll (regardless of whether standard cost is 100 discs, 2 codex, etc.)
334	      const shredderTicketCost = mult * 1;
335	
336	      let hasPaid = false;
337	      let paidViaShredder = false;
338	
339	      // Check if explicitly using Shredder Ticket or if the pack itself requires Shredder Ticket
340	      if (useUniversalShredderTicket || currency === 'shredder-ticket') {
341	        if (inv.shredderTickets >= shredderTicketCost) {
342	          inv.spendShredderTickets(shredderTicketCost);
343	          hasPaid = true;
344	          paidViaShredder = true;
345	        }
346	      } else {
347	        // Attempt standard currency consumption first
348	        if (currency === 'angel-roll' && inv.angelRollTickets >= standardCost) {
349	          inv.spendAngelTickets(standardCost);
350	          hasPaid = true;
351	        } else if (currency === 'solar-roll' && inv.solarRollTickets >= standardCost) {
352	          inv.spendSolarTickets(standardCost);
353	          hasPaid = true;
354	        } else if (currency === 'codex-roll' && inv.codexRollTickets >= standardCost) {
355	          inv.spendCodexTickets(standardCost);
356	          hasPaid = true;
357	        } else if (currency === 'discs') {
358	          const vinylDiscs = useVinylStore.getState().discs || inv.discs || 0;
359	          if (vinylDiscs >= standardCost) {
360	            inv.spendDiscs(standardCost);
361	            useVinylStore.getState().spendDiscs(standardCost);
362	            hasPaid = true;
363	          }
364	        }
365	
366	        // Seamless Wildcard Fallback: If standard currency is insufficient, allow 1:1 Shredder Ticket substitute
367	        if (!hasPaid && inv.shredderTickets >= shredderTicketCost) {
368	          inv.spendShredderTickets(shredderTicketCost);
369	          hasPaid = true;
370	          paidViaShredder = true;
371	        }
372	      }
373	
374	      if (!hasPaid) {
375	        return null;
376	      }
377	
378	      // 2. Execute multi-roll via compiled engine
379	      const { items, dict } = executePackRoll(deck, mult);
380	
381	      // 3. Inject energy cores if any & accumulate cross-app resources
382	      let newReserves = { ...get().energyReserves };
383	      let totalDnaReward = 0;
384	      let totalRedOrbsReward = 0;
385	      let totalTimeRewardSeconds = 0;
386	
387	      for (const item of items) {
388	        if (item.category === 'energy-core' && item.energyCores) {
389	          for (const core of item.energyCores) {
390	            newReserves[core.attribute] = (newReserves[core.attribute] || 0) + core.amount;
391	          }
392	        }
393	        if (item.dnaReward) {
394	          totalDnaReward += item.dnaReward;
395	        }
396	        if (item.redOrbsReward) {
397	          totalRedOrbsReward += item.redOrbsReward;
398	        }
399	        if (item.timeRewardSeconds) {
400	          totalTimeRewardSeconds += item.timeRewardSeconds;
401	        }
402	      }
403	
404	      // 4. Update Arc Jurassic resources live in shared store & backend
405	      if (totalDnaReward > 0 || totalRedOrbsReward > 0 || totalTimeRewardSeconds > 0) {
406	        useArcJurassicStore.getState().addResources({
407	          dna: totalDnaReward,
408	          red_orbs: totalRedOrbsReward,
409	          jurassic_time: totalTimeRewardSeconds,
410	        });
411	      }
412	
413	      // 4. Update lifetime dictionary tallies
414	      const updatedLifetimeDict = { ...get().lifetimeDict };
415	      for (const [key, count] of Object.entries(dict)) {
416	        updatedLifetimeDict[key] = (updatedLifetimeDict[key] || 0) + count;
417	      }
418	
419	      // 5. Atomic state update
420	      set((state) => ({
421	        vault: [...items, ...state.vault],
422	        energyReserves: newReserves,
423	        totalPulls: state.totalPulls + items.length,
424	        totalPacksOpened: state.totalPacksOpened + mult,
425	        lifetimeDict: updatedLifetimeDict,
426	      }));
427	
428	      // 6. Persist & Audit
429	      syncVaultToBackend(get);
430	      logAuditEvent('GACHA_PACK_BATCH_PULL', {
431	        deckId: deck.id,
432	        deckTitle: deck.title,
433	        multiplier: mult,
434	        itemCount: items.length,
435	        ticketCost: paidViaShredder ? shredderTicketCost : standardCost,
436	        paidViaShredder,
437	      });
438	
439	      return { items, dict };
440	    },
441	
442	    // -----------------------------------------------------------------------
443	    // PULL FROM PACK (Single Roll)
444	    // -----------------------------------------------------------------------
445	    pullFromPack: (ticketType: TicketType) => {
446	      const inv = useInventoryStore.getState();
447	
448	      // 1. Check ticket availability and consume
449	      let hasTicket = false;
450	      if (ticketType === 'angel-roll' && inv.angelRollTickets >= 1) {
451	        inv.spendAngelTickets(1);
452	        hasTicket = true;
453	      } else if (ticketType === 'solar-roll' && inv.solarRollTickets >= 1) {
454	        inv.spendSolarTickets(1);
455	        hasTicket = true;
456	      } else if (ticketType === 'codex-roll' && inv.codexRollTickets >= 1) {
457	        inv.spendCodexTickets(1);
458	        hasTicket = true;
459	      } else if (ticketType === 'shredder-ticket' && inv.shredderTickets >= 1) {
460	        inv.spendShredderTickets(1);
461	        hasTicket = true;
462	      }
463	
464	      if (!hasTicket) {
465	        return null;
466	      }
467	
468	      // 2. Generate item
469	      const item = generateRandomItem(ticketType);
470	
471	      // 3. If energy core, auto-inject into energy reserves
472	      let newReserves = { ...get().energyReserves };
473	      if (item.category === 'energy-core' && item.energyCores) {
474	        for (const core of item.energyCores) {
475	          newReserves[core.attribute] = (newReserves[core.attribute] || 0) + core.amount;
476	        }
477	      }
478	
479	      // 4. Update store state
480	      set((state) => ({
481	        vault: [item, ...state.vault],
482	        energyReserves: newReserves,
483	        totalPulls: state.totalPulls + 1,
484	      }));
485	
486	      // 5. Persist to backend and log audit event
487	      syncVaultToBackend(get);
488	      logAuditEvent('GACHA_PULL', {
489	        ticketType,
490	        itemId: item.id,
491	        itemName: item.name,
492	        category: item.category,
493	        rarity: item.rarity,
494	        rank: item.rank,
495	      });
496	
497	      return item;
498	    },
499	
500	    // -----------------------------------------------------------------------
501	    // ARENA EQUIPMENT ACTIONS
502	    // -----------------------------------------------------------------------
503	    equipRelic: (slotIndex: number, itemId: string) => {
504	      const item = get().vault.find((i) => i.id === itemId);
505	      if (!item || item.category !== 'relic') return;
506	
507	      set((state) => {
508	        const newSlots = state.arenaSlots.map((slot) => {
509	          if (slot.equippedItem?.id === itemId && slot.slotIndex !== slotIndex) {
510	            return { ...slot, equippedItem: null };
511	          }
512	          if (slot.slotIndex === slotIndex) {
513	            return { ...slot, equippedItem: item };
514	          }
515	          return slot;
516	        });
517	        return { arenaSlots: newSlots };
518	      });
519	
520	      syncVaultToBackend(get);
521	      logAuditEvent('RELIC_EQUIPPED', { slotIndex, itemId, relicName: item.name });
522	    },
523	
524	    unequipRelic: (slotIndex: number) => {
525	      set((state) => ({
526	        arenaSlots: state.arenaSlots.map((s) =>
527	          s.slotIndex === slotIndex ? { ...s, equippedItem: null } : s
528	        ),
529	      }));
530	
531	      syncVaultToBackend(get);
532	      logAuditEvent('RELIC_UNEQUIPPED', { slotIndex });
533	    },
534	
535	    // -----------------------------------------------------------------------
536	    // GOLDEN HOURS & HAZARD LEVEL
537	    // -----------------------------------------------------------------------
538	    addGoldenHours: (hours: number) => {
539	      set((state) => {
540	        const newHours = Math.max(0, state.hazardProfile.goldenHours + hours);
541	        return {
542	          hazardProfile: {
543	            goldenHours: Math.round(newHours * 100) / 100,
544	            hazardLevel: calculateHazardLevel(newHours),
545	          },
546	        };
547	      });
548	    },
549	
550	    // -----------------------------------------------------------------------
551	    // ENERGY CONSUMPTION
552	    // -----------------------------------------------------------------------
553	    consumeEnergy: (attribute: ElementalAttribute, amount: number) => {
554	      const current = get().energyReserves[attribute] || 0;
555	      if (current < amount) return false;
556	
557	      set((state) => ({
558	        energyReserves: {
559	          ...state.energyReserves,
560	          [attribute]: current - amount,
561	        },
562	      }));
563	
564	      syncVaultToBackend(get);
565	      logAuditEvent('ENERGY_CONSUMED', { attribute, amount });
566	      return true;
567	    },
568	
569	    // -----------------------------------------------------------------------
570	    // VAULT FILTERING
571	    // -----------------------------------------------------------------------
572	    getVaultByCategory: (category: VaultCategory) => {
573	      const vault = get().vault;
574	      switch (category) {
575	        case 'tactical':
576	          return vault.filter((i) => i.category === 'relic');
577	        case 'collection':
578	          return vault.filter((i) => i.category === 'collectible');
579	        case 'energy':
580	          return vault.filter((i) => i.category === 'energy-core');
581	      }
582	    },
583	
584	    // -----------------------------------------------------------------------
585	    // DEVELOPER / SANDBOX CHEAT SUITE
586	    // -----------------------------------------------------------------------
587	    injectSampleRelics: () => {
588	      const sampleRelics: PullItem[] = [
589	        {
590	          id: `cheat_relic_1_${Date.now()}`,
591	          name: 'Babylonian Star Scepter',
592	          description: 'Forged from the primordial core of Babylon. Bestows supreme cosmic authority with moderate agility drain.',
593	          category: 'relic',
594	          rarity: 'legendary',
595	          rank: '✦',
596	          score: 11.45,
