82	// Option at the bottom of the Include selector list (used as default fallback when a channel is approved/hidden/deleted)
83	export function computeBottomPlaylistOption(
84	  channelList: ChannelOriginItem[],
85	  customPlaylists: CustomPlaylist[],
86	  channelMetaMap: Record<string, { status: string }>,
87	  excludeChannel?: string
88	): string {
89	  // Sort deterministically: count descending, then name ascending for 100% stable ordering
90	  const sorted = [...channelList].sort(
91	    (a, b) => b.count - a.count || a.name.localeCompare(b.name)
92	  );
93	
94	  // 1. Bottom-most group: Raw Playlists
95	  const raw = sorted.filter(
96	    (c) =>
97	      c.name !== excludeChannel &&
98	      (channelMetaMap[c.name]?.status || 'raw') === 'raw' &&
99	      channelMetaMap[c.name]?.status !== 'approved'
100	  );
101	  if (raw.length > 0) {
102	    return raw[raw.length - 1].name;
103	  }
104	
105	  // 2. Cleaning Playlists
106	  const cleaning = sorted.filter(
107	    (c) =>
108	      c.name !== excludeChannel &&
109	      channelMetaMap[c.name]?.status === 'cleaning' &&
110	      channelMetaMap[c.name]?.status !== 'approved'
111	  );
112	  if (cleaning.length > 0) {
113	    return cleaning[cleaning.length - 1].name;
114	  }
115	
116	  // 3. Custom Playlists
117	  const eligibleCustom = customPlaylists.filter(
118	    (p) => p.id !== excludeChannel && `CUSTOM:${p.id}` !== excludeChannel
119	  );
120	  if (eligibleCustom.length > 0) {
121	    return `CUSTOM:${eligibleCustom[eligibleCustom.length - 1].id}`;
122	  }
123	
124	  return 'ALL';
125	}
