444	          if (compMatches) return true;
445	          return c.name.toLowerCase().includes(q) || (c.description?.toLowerCase().includes(q) ?? false);
446	        })
447	        .sort((a, b) => a.name.localeCompare(b.name, undefined, { sensitivity: 'base' }));
448	
449	      if (memberItems.length > 0) {
