451	          id: comp.id,
452	          title: comp.name,
453	          emoji: comp.emoji || (isAlbum ? '📚' : '🗂️'),
454	          items: memberItems,
455	        });
456	      }
457	    }
458	
459	    // 4. Standalone items = candidates not belonging to any compilation
460	    const standaloneItems = allCandidates
461	      .filter((item) => {
462	        if (assignedItemIds.has(item.id)) return false;
463	        if (!q) return true;
464	        return item.name.toLowerCase().includes(q) || (item.description?.toLowerCase().includes(q) ?? false);
465	      })
466	      .sort((a, b) => a.name.localeCompare(b.name, undefined, { sensitivity: 'base' }));
