472	        emoji: isAlbum ? '💿' : '🎸',
473	        isStandalone: true,
474	        items: standaloneItems,
475	      });
476	    }
477	
478	    return groups;
479	  }, [activePicker, customPlaylists, playlistSearchQuery]);
480	
481	  const totalAvailableForActivePicker = useMemo(() => {
482	    return groupedPlaylistsForActivePicker.reduce((sum, g) => sum + g.items.length, 0);
483	  }, [groupedPlaylistsForActivePicker]);
484	
485	  const showToast = useCallback((message: string, type: 'info' | 'success' | 'warn' | 'error' = 'info') => {
486	    setToast({ message, type });
487	    setTimeout(() => {
488	      if (isMountedRef.current) setToast(null);
489	    }, 3000);
490	  }, []);
491	  showToastRef.current = showToast;
