493	  // Single-choice: Select/assign an Album for the current song
494	  const handleSelectAlbumForSong = useCallback(
495	    async (targetAlbum: CustomPlaylist | null) => {
496	      if (!currentTrack) return;
497	      const songId = currentTrack.id;
498	
499	      if (targetAlbum && currentAlbum?.id === targetAlbum.id) {
500	        setActivePicker(null);
