504	      setSavingPlaylistId(targetAlbum ? targetAlbum.id : 'unassign_album');
505	      try {
506	        // 1. Remove song from previous album if changing or unassigning
507	        if (currentAlbum) {
508	          const updatedPrev: CustomPlaylist = {
509	            ...currentAlbum,
510	            include_songs: currentAlbum.include_songs.filter((id) => id !== songId),
511	            updated_at: new Date().toISOString(),
512	          };
513	          await saveCustomPlaylist(targetProjectId, updatedPrev);
514	          updateCustomPlaylist(updatedPrev);
515	        }
516	
517	        // 2. Add song to target album if selected
518	        if (targetAlbum) {
