802	  const selectWeightedTrack = useCallback((list: PlaylistItem[], excludeIdx: number = -1) => {
803	    if (!list || list.length === 0) {
804	      return { index: -1, probability: 0 };
805	    }
806	
807	    const n = list.length;
808	    if (n === 1) {
809	      return { index: 0, probability: 100 };
810	    }
811	
812	    let totalWeight = 0;
813	    for (let i = 0; i < n; i++) {
814	      if (i === excludeIdx) continue;
815	      const count = displayStatsRef.current[list[i].id]?.played ?? 0;
816	      totalWeight += 1 / (count + 1);
817	    }
818	
819	    if (totalWeight <= 0) return { index: 0, probability: 100 };
820	
821	    let randomVal = Math.random() * totalWeight;
822	    let selectedIndex = 0;
823	    let selectedWeight = 1;
824	
825	    for (let i = 0; i < n; i++) {
826	      if (i === excludeIdx) continue;
827	      const count = displayStatsRef.current[list[i].id]?.played ?? 0;
828	      const w = 1 / (count + 1);
829	      randomVal -= w;
830	      if (randomVal <= 0) {
831	        selectedIndex = i;
832	        selectedWeight = w;
833	        break;
834	      }
835	    }
836	
837	    const probability = (selectedWeight / totalWeight) * 100;
838	    return { index: selectedIndex, probability };
