      .filter((item) => {
        if (assignedItemIds.has(item.id)) return false;
        if (!q) return true;
        return item.name.toLowerCase().includes(q) || (item.description?.toLowerCase().includes(q) ?? false);
      })
      .sort((a, b) => a.name.localeCompare(b.name, undefined, { sensitivity: 'base' }));

