      });
      loadData(fallback, hazardCap, excludedChannels);
    }
  } else if (selectedChannel !== 'ALL' && selectedChannel !== 'DISCOVERY:unassigned' && !selectedChannel.startsWith('CUSTOM:')) {
    const st = channelMetaMap[selectedChannel]?.status;
    if (st === 'approved') {
      const fallback = getBottomPlaylistOptionRef.current
        ? getBottomPlaylistOptionRef.current(undefined, undefined, undefined, selectedChannel)
        : 'ALL';
      if (fallback !== selectedChannel) {
        setSelectedChannel(fallback);
        selectedChannelRef.current = fallback;
        saveFilterConfig(targetProjectId, {
          selectedChannel: fallback,
          excludedChannels: excludedChannelsRef.current,
          discoveryMode: isDiscoveryModeRef.current,
        });

