export async function saveFilterConfig(
  projectId: string,
  config: SavedFilterConfig
): Promise<boolean> {
  try {
    await executeOrder({
      project_id: projectId,
      tier: '5',
      order: {
        action: 'upsert',
        key: 'filter_settings',
        data: {
          excluded_channels: config.excludedChannels,
          hazard_cap: config.hazardCap || 'ALL',
          selected_channel: config.selectedChannel || 'ALL',
          discovery_mode: Boolean(config.discoveryMode ?? config.onlyUnassignedAlbums ?? false),
          folded_sections: config.foldedSections ? JSON.stringify(config.foldedSections) : undefined,
          updated_at: new Date().toISOString(),
        },
      },
    });
    return true;
  } catch (e) {
    console.error('[Engine] Failed to persist filter settings to Tier 5:', e);
    return false;
  }
}

