// Workflow: If blocking the only/last video of a substandard playlist -> delete immediately without buffer and stream next bottom playlist!
if (action === 'block') {
  const curSelected = selectedChannelRef.current;
  const isChannelTarget = curSelected === activeTrack.channel;
  const isCustomTarget = curSelected.startsWith('CUSTOM:');
  const chItem = channelList.find((c) => c.name === activeTrack.channel);

  // Check if the channel or playlist is now empty (only 1 track existed or buffer now empty with catalog count <= 1)
  const isChannelEmpty =
    isChannelTarget && (updatedList.length === 0 || totalCatalogCount <= 1 || (chItem && chItem.count <= 1));
  const isCustomEmpty =
    isCustomTarget && (updatedList.length === 0 || totalCatalogCount <= 1);
  const isStandaloneChannelEmpty =
    !isCustomTarget && chItem && chItem.count <= 1;

  if (isChannelEmpty || isCustomEmpty || (isStandaloneChannelEmpty && updatedList.length === 0)) {
    let nextChannels = channelList;
    let nextPls = customPlaylists;
    let nextMeta = { ...channelMetaMap };

    if (isCustomEmpty) {
      const plId = curSelected.replace('CUSTOM:', '');
      const plObj = customPlaylists.find((p) => p.id === plId);
      try {
        await deleteCustomPlaylist(targetProjectId, plId);
        removeCustomPlaylist(plId);
        nextPls = customPlaylists.filter((p) => p.id !== plId);
        showToast(`🗑️ Playlist "${plObj?.name || plId}" deleted (0 songs remaining)`, 'warn');
      } catch (err) {
        console.warn('[handleNextSong] Failed to delete empty custom playlist:', err);
      }
    } else {
      const chName = activeTrack.channel;
      const chId = activeTrack.channel_id;
      try {
        await purgeChannelSongs(targetProjectId, chName, chId);
        nextChannels = channelList.filter((c) => c.name !== chName);
        setChannelList(nextChannels);
        delete nextMeta[chName];
        if (chId) delete nextMeta[chId];
        setChannelMetaMap(nextMeta);
        showToast(`🗑️ Playlist "${chName}" deleted & purged`, 'warn');
      } catch (err) {
        console.warn('[handleNextSong] Failed to purge empty channel:', err);
      }
    }

    // Immediate buffer sync on block-eradication
    try {
      const currentOutbox = useVinylStore.getState().offlineOutbox || [];
      if (currentOutbox.length > 0) {
        const res = await flushOfflineEvents(targetProjectId, currentOutbox);
        if (res.success) clearOfflineOutbox();
      }
      await syncTier2ToTier3(targetProjectId, true);
      await syncTier3ToTier4(targetProjectId);
      setPendingLogsCount(0);
    } catch (e) {
      console.warn('[handleNextSong] Post-block sync warning:', e);
    }

    // Directly select and play the next bottom playlist
    const nextBottom = getBottomPlaylistOption(nextChannels, nextPls, nextMeta, curSelected);
    setSelectedChannel(nextBottom);
    selectedChannelRef.current = nextBottom;
    saveFilterConfig(targetProjectId, {
      selectedChannel: nextBottom,
      excludedChannels: excludedChannelsRef.current,
    });

    seenIdsRef.current.clear();

    showToast(`▶ Switched to bottom playlist: "${nextBottom === 'ALL' ? 'All Catalog' : nextBottom}"`, 'info');
    await loadDataRef.current(nextBottom, hazardCapRef.current, excludedChannelsRef.current);
    return;
  }
}

