    fetchChannelOrigins(targetProjectId, filterOpts).catch(() => []),
  ]);
  sampledData = sData;
  if (filteredChannels && filteredChannels.length >= 0) {
    const sorted = [...filteredChannels].sort(
      (a, b) => b.count - a.count || a.name.localeCompare(b.name)
    );
    setChannelList(sorted);
  }
}

const { tracks, totalCatalogCount: count, statsMap } = sampledData;

